@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1670  cases=52
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-165
  @fn seedItems(h, takes, srcLen)  @ 181-186
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 188-197
  @fn trackList(trackCount)  @ 199-205
  @fn mapTracker(harness, inst, trackCount)  @ 210-224
      -- A tracker bound to the take 'i0' over a track list of the given width, with
      -- i0's placement as the caller states it; inst = nil binds it into no instance.
      -- Returns the page's tv, and the harness behind it for the cmgr.

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 228-236
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 239-248
  @case 'focusState before any render returns both bits false'  [harness]  @ 251-258
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 264-277
  @case 'with no live instance, the new take mints a parked slot and selects it'  [harness]  @ 281-298
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 304-325
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 331-349
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 356-374
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 380-413
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 417-441
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 447-477
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 481-502
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 506-519
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 525-559
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 563-577
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 581-604
  @case 'a track step lands on the placement overlapping the current instance most'  [harness]  @ 608-644
  @case 'with nothing overlapping, a track step lands on the placement nearest in time'  [harness]  @ 648-683
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 690-707
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 711-734
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 738-761
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 765-800
  @case 'the walk steps along the track's placements in start order, holding at the ends'  [harness]  @ 804-852
  @case 'a walk into another slot resets the caret; within one slot the caret holds'  [harness]  @ 856-893
  @case 'deleting the instance drops that placement and lands on the one before it'  [harness]  @ 897-931
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 935-951
  @case 'the map window centres the bound column, and clamps it at both ends'  [harness]  @ 960-978
  @case 'the map window pages time, a start in the last bar opening the next page'  [harness]  @ 982-998
  @case 'with the tracker in no instance the map window pages on the edit cursor'  [harness]  @ 1002-1009
  @case 'the map window carries the takes over it, the current instance marked'  [harness]  @ 1013-1024
  @case 'the map window carries the transport it meets, and only that'  [harness]  @ 1028-1051
  @case 'the map loop candidate snaps to the cell, widens to one, and holds at 0'  [harness]  @ 1055-1074
  @case 'the map drives the transport, and a hand-set loop drops loop to item'  [harness]  @ 1078-1088
  @case 'the pin key holds the map up as the palette default, and drops it when pressed again'  [harness]  @ 1092-1101
  @case 'a gesture raises the map, and it falls at the next command'  [harness]  @ 1105-1146
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 1150-1177
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 1181-1205
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 1212-1233
  @case 'the play row and the head row count from the source origin, not the start'  [harness]  @ 1239-1263
  @case 'a dive carries the arrange QN to the caret row, and the caret hands it back'  [harness]  @ 1270-1289
  @case 'a caret outside the rendered span hands back the row the span stops at'  [harness]  @ 1293-1312
  @case 'leaving the tracker puts the arrange caret where the tracker caret is'  [harness]  @ 1316-1338
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 1344-1362
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 1366-1384
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 1388-1410
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 1414-1438
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 1444-1499
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 1507-1536
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 1542-1585
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1591-1605
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1612-1644
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1648-1668

